Json VirtualInstruments::Measure(const std::string& id,const std::string& target,const Json& frame)const{
    std::string node=target;Json value;int pad=-1;
    if(target.starts_with("wire.")){for(const auto& edge:c_.board->Edges())if(target==edge.id+".a" || target==edge.id+".b")node=target.ends_with(".a")?edge.net:edge.endpoint;}
    if(target.starts_with("port:")){auto name=target.substr(5);if(frame.at("outputs").contains(name)){bool high=frame.at("outputs").at(name);value=ExplainState13({{"dut:"+name,uint8_t(high?15:13)}});}else if(frame.contains("sampled_inputs") && frame.at("sampled_inputs").contains(name)){bool high=frame.at("sampled_inputs").at(name);value=ExplainState13({{"dut-input:"+name,uint8_t(high?15:13)}});}else{bool exists=false;for(const auto& port:c_.manifest.ports)for(const auto& bit:port.bits)exists|=c_.manifest.Label(bit)==name;if(!exists)throw std::runtime_error("E_PROBE_PORT");value=ExplainState13({});}}
    if(value.is_null()){if(!frame.at("board").at("nodes").contains(node))throw std::runtime_error("E_PROBE_TARGET");value=frame.at("board").at("nodes").at(node);}
    if(node.starts_with("pad."))pad=std::stoi(node.substr(4));else for(const auto& edge:c_.board->Edges())if(edge.endpoint==node)pad=std::stoi(edge.net.substr(4));
    Json voltage=nullptr;if(value.at("valid")==true && pad>0){if(value.at("logic")=="0")voltage=0;else{auto p=c_.electrical.device.pads.find(pad);if(p!=c_.electrical.device.pads.end()){auto bank=c_.electrical.power.vccio_mv.find(p->second.vendor_bank_id);if(bank!=c_.electrical.power.vccio_mv.end() && bank->second)voltage=*bank->second;}}}
    return {{"probe_id",id},{"target",target},{"resolved_endpoint",node},{"position",frame.at("position")},{"state",value},{"nominal_mv",voltage},{"voltage_model","digital_nominal_estimate_not_spice"},{"read_only",true}};
}
Json VirtualInstruments::Command(const Json& cmd,const Json& frame){std::string op=cmd.at("op");
    if(op=="probe.attach"){std::string id=cmd.at("probe_id"),target=cmd.at("target");if(id.empty() || id.size()>64 || probes_.size()>=64 || probes_.count(id))throw std::runtime_error("E_PROBE_QUOTA_OR_ID");auto measurement=Measure(id,target,frame);probes_[id]=target;return measurement;}
    if(op=="probe.detach"){probes_.erase(cmd.at("probe_id"));return {{"status","detached"}};}
    if(op=="probe.read"){std::string id=cmd.at("probe_id");auto measurement=Measure(id,probes_.at(id),frame);if(evidence_.size()>=4096)throw std::runtime_error("E_EVIDENCE_QUOTA");evidence_.push_back(measurement);return measurement;}
    if(op=="capture.arm"){auto cfg=cmd.at("config");auto integer=[](const Json& v,uint64_t lo,uint64_t hi){return v.is_number_integer() && (!v.is_number_integer() || v.get<int64_t>()>=0) && v.get<uint64_t>()>=lo && v.get<uint64_t>()<=hi;};for(auto key:{"depth","pretrigger","decimation"})if(!cfg.contains(key) || !integer(cfg.at(key),key==std::string("pretrigger")?0:1,4096))throw std::runtime_error("E_CAPTURE_CONFIG");for(auto key:{"max_samples","max_edges"})if(cfg.contains(key) && !integer(cfg.at(key),1,1000000))throw std::runtime_error("E_CAPTURE_BUDGET");if(cfg.contains("sample_en") && !cfg.at("sample_en").is_boolean())throw std::runtime_error("E_CAPTURE_GATE");if(cfg.contains("gate"))Measure("gate",cfg.at("gate"),frame);if(cfg.at("source")!="virtual_probe" || cfg.at("targets").empty() || cfg.at("targets").size()>32 || cfg.at("depth").get<unsigned>()<2 || cfg.at("depth").get<unsigned>()>4096 || cfg.at("pretrigger").get<unsigned>()>=cfg.at("depth").get<unsigned>() || cfg.at("decimation").get<unsigned>()<1 || cfg.at("decimation").get<unsigned>()>255)throw std::runtime_error("E_CAPTURE_CONFIG");for(const auto& target:cfg.at("targets"))Measure("check",target,frame);auto trigger=cfg.at("trigger");auto kind=trigger.at("kind").get<std::string>();if(kind!="mask_equal" && kind!="edge_rising" && kind!="edge_falling" && kind!="stall" && kind!="timeout")throw std::runtime_error("E_CAPTURE_TRIGGER");if(!trigger.at("count").is_number_unsigned() && !trigger.at("count").is_number_integer() || trigger.at("count").get<int64_t>()<1)throw std::runtime_error("E_CAPTURE_TRIGGER");if(!integer(trigger.at("count"),1,65535) || !integer(trigger.at("mask"),0,0xffffffffu) || !integer(trigger.at("value"),0,0xffffffffu))throw std::runtime_error("E_CAPTURE_TRIGGER");config_=cfg;samples_=Json::array();pre_.clear();armed_=true;triggered_=false;clock_high_=frame.at("p1").at("clock_high");edges_=decimated_=previous_=hits_=post_=trigger_index_=0;return Capture();}
    if(op=="capture.read")return Capture();if(op=="evidence.query")return {{"measurements",evidence_},{"capture",Capture()}};throw std::runtime_error("E_INSTRUMENT_COMMAND");
}
Json VirtualInstruments::Current(const Json& frame)const{Json readings=Json::array();for(const auto& [id,target]:probes_)readings.push_back(Measure(id,target,frame));return readings;}
void VirtualInstruments::Observe(const Json& frame){bool high=frame.at("p1").at("clock_high");bool rising=high && !clock_high_;clock_high_=high;if(!armed_ || !rising)return;++edges_;if(edges_>config_.value("max_edges",1000000u)){armed_=false;return;}if(!config_.value("sample_en",true))return;if(config_.contains("gate")){auto gate=Measure("gate",config_.at("gate"),frame);if(!gate.at("state").at("valid").get<bool>() || gate.at("state").at("logic")!="1")return;}unsigned dec=config_.at("decimation");if(post_++%dec)return;
    uint32_t packed=0,valid=0;size_t bit=0;for(const auto& t:config_.at("targets")){auto m=Measure("capture",t,frame);if(m.at("state").at("valid")==true){valid|=uint32_t(1)<<bit;if(m.at("state").at("logic")=="1")packed|=uint32_t(1)<<bit;}++bit;}
    Json sample={{"tick",frame.at("position").at("tick")},{"edge_index",std::to_string(edges_)},{"sample_index",std::to_string(decimated_++)},{"value",packed},{"valid_mask",valid}};const auto& trigger=config_.at("trigger");uint32_t mask=trigger.at("mask"),wanted=trigger.at("value");auto kind=trigger.at("kind").get<std::string>();auto now=packed&mask;bool hit=false;
    if(kind=="mask_equal")hit=now==wanted;else if(kind=="edge_rising")hit=((~previous_)&now)!=0;else if(kind=="edge_falling")hit=(previous_&~now)!=0;else if(kind=="stall")hit=now==previous_;else hit=decimated_>=trigger.at("count").get<uint64_t>();
    if((valid&mask)!=mask)hit=false;if(kind=="timeout")hits_=hit?trigger.at("count").get<uint64_t>():0;else if(hit)++hits_;else if(kind=="stall")hits_=0;previous_=now;
    if(!triggered_ && hits_>=trigger.at("count").get<uint64_t>()){triggered_=true;for(const auto& old:pre_)samples_.push_back(old);trigger_index_=samples_.size();pre_.clear();}
    if(triggered_){samples_.push_back(sample);if(samples_.size()>=config_.at("depth").get<size_t>())armed_=false;}
    else{pre_.push_back(sample);while(pre_.size()>config_.at("pretrigger").get<size_t>())pre_.pop_front();if(decimated_>=config_.value("max_samples",100000u))armed_=false;}
}
Json VirtualInstruments::Capture()const{return {{"schema","sigflow.virtual-capture.v1"},{"source","virtual_probe"},{"layout","circular_pretrigger_chronological"},{"sample_phase","post_eval"},{"armed",armed_},{"triggered",triggered_},{"trigger_index",trigger_index_},{"decimation",config_.is_null()?1:config_.value("decimation",1)},{"sample_clock_hz",std::to_string(c_.frequency_hz)},{"clock_pad",c_.clock_pad},{"source_fingerprint",c_.manifest.source_sha256},{"targets",config_.is_null()?Json::array():config_.value("targets",Json::array())},{"samples",samples_}};}
Json VirtualInstruments::Compare(const Json& expected,const Json& actual){
    for(auto field:{"sample_clock_hz","decimation","clock_pad","source_fingerprint","targets"})if(expected.at(field)!=actual.at(field))return {{"status","inconclusive"},{"reason",std::string("E_CAPTURE_DOMAIN: ")+field}};
    if(expected.value("sample_phase",std::string())!=actual.value("sample_phase",std::string()))return {{"status","inconclusive"},{"reason","E_CAPTURE_SAMPLE_PHASE"}};
    if(!expected.at("triggered").get<bool>() || !actual.at("triggered").get<bool>())return {{"status","inconclusive"},{"reason","E_TRIGGER_NOT_OBSERVED"}};
    auto e0=expected.at("trigger_index").get<int64_t>(),a0=actual.at("trigger_index").get<int64_t>();
    if(e0<0 || a0<0 || e0>=int64_t(expected.at("samples").size()) || a0>=int64_t(actual.at("samples").size()))return {{"status","inconclusive"},{"reason","E_CAPTURE_TRIGGER_INDEX"}};
    auto edge=[](const Json& s){return std::stoll(s.at("edge_index").get<std::string>());};
    auto checkEdges=[&](const Json& c){const auto& ss=c.at("samples");for(size_t i=1;i<ss.size();++i)if(edge(ss[i])<=edge(ss[i-1]) || (edge(ss[i])-edge(ss[i-1]))%c.at("decimation").get<int64_t>())return false;return true;};
    if(!checkEdges(expected) || !checkEdges(actual))return {{"status","inconclusive"},{"reason","E_CAPTURE_EDGE_ORDER"}};
    int64_t lo=std::max(-e0,-a0),hi=std::min(int64_t(expected.at("samples").size())-e0,int64_t(actual.at("samples").size())-a0);
    if(lo>=hi)return {{"status","inconclusive"},{"reason","E_CAPTURE_NO_OVERLAP"}};
    for(int64_t i=lo;i<hi;++i)if(edge(expected.at("samples").at(e0+i))-edge(expected.at("samples").at(e0))!=edge(actual.at("samples").at(a0+i))-edge(actual.at("samples").at(a0)))return {{"status","inconclusive"},{"reason","E_CAPTURE_EDGE_ALIGNMENT"},{"sample_offset",i}};
    for(int64_t i=lo;i<hi;++i){const auto& e=expected.at("samples").at(e0+i);const auto& a=actual.at("samples").at(a0+i);auto ev=e.at("value").get<uint32_t>(),av=a.at("value").get<uint32_t>(),em=e.at("valid_mask").get<uint32_t>(),am=a.at("valid_mask").get<uint32_t>();for(size_t bit=0;bit<actual.at("targets").size();++bit)if(((ev^av)&em&am | (em^am))&(uint32_t(1)<<bit))return {{"status","diverged"},{"first_failure_tick",a.at("tick")},{"sample_offset",i},{"signal",actual.at("targets").at(bit)},{"expected",bool(ev&(uint32_t(1)<<bit))},{"actual",bool(av&(uint32_t(1)<<bit))},{"expected_valid",bool(em&(uint32_t(1)<<bit))},{"actual_valid",bool(am&(uint32_t(1)<<bit))}};}
    return {{"status","matched"},{"samples_compared",hi-lo}};
}
